ROOT=Path(__file__).resolve().parents[1]; BEST=ROOT/'07_Bestiary'; F=BEST/'09_Laut_Rangkaruna'; R=BEST/'_audit'; GAME=ROOT/'10_Game Project/Tales of The Dark Time'
REG='03_Region/09_Laut_Rangkaruna/Laut_Rangkaruna.md'; WORLD='02_World/Laut_Rangkaruna.md'; P3='08_Story/02_Prologue/03_Teror_di_Pesisir_Timur.md'; P5='08_Story/02_Prologue/05_Rahasia_Sang_Echomancer.md'; AQUALIS='03_Region/01_Mandala Kingdom/Cities & Town/Aqualis.md'
# title, description, form, behavior, habitat, tale title, tale, sources, unresolved
E={
'Hiu_Purba_Tulang':('Hiu Purba Tulang','Kerangka hiu raksasa yang digerakkan mana kegelapan serta dendam para pelaut tenggelam. Ia melintas di antara bangkai kapal tanpa tubuh hidup, tetapi rahang tulangnya masih mampu merobek lambung baja. Keberadaannya membuat kuburan kapal Rangkaruna menjadi tempat maut bahkan bagi penyelam yang mengira pemangsa di sana telah lama mati.','Tengkoraknya lebar dengan deretan taring tulang tidak rata. Ruas tulang belakang memanjang menuju ekor yang bergerak seolah masih memiliki otot. Sirip hanya tersisa sebagai rangka keras, diselimuti kabut hitam tipis yang menjaga susunannya tetap utuh. Cahaya redup terlihat dalam rongga mata dan sela rusuk. Pecahan rantai, jaring, atau kayu kapal kerap tersangkut pada kerangkanya.','Agresif terhadap gerakan dan getaran di wilayah bangkai kapal. Ia mengitari sasaran, menembus celah reruntuhan, lalu menyerang dari sisi yang tertutup papan. Kerangka yang terpisah dapat kembali ditarik oleh kabut pengikatnya, tetapi batas pemulihan itu belum diketahui. Ia bukan Dhemit yang telah dipastikan; sumber hanya menyebut mana gelap dan dendam pelaut sebagai penggerak.','Kuburan Kapal Laut Rangkaruna, terutama cekungan tempat arus mengumpulkan puing, jangkar, dan tulang pelaut. Struktur kapal tenggelam memberi jalur berlindung sekaligus perangkap bagi mangsa.','Rahang di Antara Tiang Patah','Seekor ikan besar masuk ke lambung kapal tenggelam untuk menghindari badai. Tulang rusuk putih bergerak di balik tiang yang patah. Hiu Purba menembus bukaan tanpa menggeser satu papan pun, kabut gelap menarik rangkanya melewati reruntuhan. Ikan itu lolos melalui lubang kecil; sang hiu kembali mengitari bangkai, menunggu getaran berikutnya.',[REG,WORLD],['Asal spiritual dan taxonomy undead/Dhemit belum dipastikan; kisah ekologis usulan.']),
'Hydra':('Hydra','Hydra Rangkaruna berkepala delapan adalah ancaman palung yang mampu menghancurkan galleon perang. Napas beracun dan gigitannya melumerkan besi. Davy Jones dikenal pernah menaklukkan salah satunya, membuktikan makhluk ini dapat dikalahkan tanpa menyamakannya dengan Hydra Jurang, penjaga berakal di Thalantira.','Tubuhnya menyerupai ular laut tebal dengan delapan leher yang tumbuh dari bahu bersisik. Setiap kepala memiliki rahang panjang, insang berlapis, dan mata yang mengawasi arah berbeda. Sirip punggung membantu tubuh utama bertahan di arus palung. Warna sisiknya biru gelap kehijauan; cairan racun meninggalkan noda pada gigi serta air di sekitar mulut.','Buas dan teritorial. Kepala-kepalanya dapat mengawasi kapal, mangsa, dan ancaman lain sekaligus, lalu menyerang dari beberapa sudut. Jika satu kepala teralihkan, kepala lain tetap menjaga tubuh utama. Ia mengejar sesuatu yang memasuki wilayah palung, tetapi tidak dinyatakan mampu berbicara atau berunding seperti Hydra Jurang.','Palung Kematian di Laut Rangkaruna. Kedalaman, arus naik, dan dinding palung memberi ruang bagi tubuh utamanya untuk tersembunyi sebelum kepala mencapai permukaan.','Delapan Bayangan di Bawah Lunas','Delapan bayangan memanjang muncul di bawah kapal pemburu. Awak mengira mereka melihat kawanan ular, sampai seluruh leher berbelok mengikuti satu tubuh. Kapal membuang muatan berbau tajam ke arah arus lain. Beberapa kepala mengejarnya, memberi waktu layar menangkap angin. Hydra kembali ke palung setelah kapal keluar dari batas wilayahnya.',[REG,WORLD,'08_Story/02_Prologue/01_Bisikan_Pulau_Terkutuk.md'],['Tidak disamakan dengan Hydra Jurang. Kisah perburuan spesifik Davy Jones tidak diperluas karena sumber hanya menyebut kemenangan.']),
'Kepiting_Batu_Karang':('Kepiting Batu Karang','Krustasea raksasa perairan dangkal yang menyamar sebagai formasi karang. Ia menunggu kapal menabrak cangkangnya, lalu bangun untuk mencapit puing dan kru yang jatuh. Dagingnya bernilai bagi pelabuhan Aqualis, tetapi perburuan langsung di habitatnya hanya dilakukan nelayan berpengalaman seperti Rama.','Cangkangnya lebar, bertingkat, dan ditumbuhi karang tajam serta lumut laut. Dua capit besar terlipat menyerupai bongkah terpisah. Mata kecil berada dalam cekungan yang tertutup saat ia diam. Kaki beruas tersembunyi di pasir, membuat seluruh tubuh tampak sebagai batu sampai dasar laut terangkat. Warna serta organisme pada cangkang berubah mengikuti tempat ia menetap.','Penyergap yang cenderung diam sampai lambung, jangkar, atau mangsa menyentuh wilayahnya. Setelah bangun ia mencapit benda terdekat dan mempertahankan posisi. Ia tidak memburu kapal jauh ke laut dalam. Nelayan dapat mengenali perbedaan arus dan susunan karang, tetapi pendekatan tetap berbahaya.','Gugusan karang dangkal di tepian Rangkaruna, khususnya jalur di luar Aqualis. Pasir dan karang hidup menyamarkan tubuhnya; lokasi itu juga cukup dekat untuk dijangkau perahu pemburu.','Buruan Pak Tua Rama','Penduduk Aqualis mengenal Rama sebagai satu-satunya nelayan yang berani mencari Kepiting Batu Karang langsung di habitatnya. Ia tidak menganggap setiap batu sebagai mangsa. Rama membaca buih, menunggu mata kecil terbuka di sela karang, lalu memilih jalan mendekat yang masih menyisakan arus untuk melarikan diri. Keberaniannya lahir dari pengetahuan laut, bukan keyakinan bahwa capit raksasa itu dapat diremehkan.',[REG,WORLD,P3,AQUALIS],['Kisah merangkum reputasi Rama; teknik pendekatan rinci adalah pengembangan usulan.']),
'Krakentis_Sang_Pemutar_Arus':('Krakentis Sang Pemutar Arus','Gurita purba raksasa yang gerakan tentakelnya dapat membentuk pusaran besar dan menyeret armada. Dalam perjalanan menuju Thalantira, Krakentis menghadang kapal Rama sampai sihir suara sang Echomancer melumpuhkan pusat sarafnya cukup lama bagi kapal untuk lolos.','Tubuh utamanya tersembunyi di kedalaman. Tentakel berduri naik mengelilingi kapal, masing-masing cukup tebal untuk menutup bagian lambung. Pengisap besar memiliki tepian keras untuk mempertahankan cengkeraman dalam badai. Kulit gelap berubah pucat pada bagian yang menegang. Mata dan pusat saraf berada dekat pangkal tubuh, jauh lebih sulit dijangkau daripada ujung tentakel.','Buas ketika kapal memasuki arus buruannya. Ia memutar tentakel di dasar laut sebelum menyerang, memakai pusaran untuk mengurangi kendali kapal. Cengkeraman terhenti sementara ketika Rama menghantam pusat sarafnya dengan gelombang sonik. Kejadian itu menunjukkan respons biologis tertentu, bukan kelemahan universal dengan durasi gameplay baru.','Perairan dalam dan Palung Kematian Rangkaruna. Ruang luas di dasar laut memungkinkan tentakel membangun putaran arus sebelum tubuh utama terlihat. Krakentis ini tidak otomatis sama dengan pemilik Kraken Tentacle di Thalantira.','Teriakan Sang Echomancer','Tentakel Krakentis menutup jalur kapal Oak hitam. Saat Hector bersiap menyerang, Rama meninggalkan kemudi dan melepaskan gelombang suara padat ke pusat saraf monster. Otot Krakentis membeku sesaat. Rama kembali merebut kemudi dan membawa kapal melewati celah tentakel sebelum makhluk itu pulih. Mereka menang bukan dengan membunuh sang pemutar arus, melainkan dengan menciptakan satu kesempatan untuk lolos.',[REG,WORLD,P5],['Kisah merangkum Prologue. Tidak disamakan dengan Kraken Tentacle Thalantira dan tidak menambah stun terkalibrasi.']),
'Lintah_Palung':('Lintah Palung','Lintah laut seukuran perahu kecil yang menyerang berkelompok dan menempel pada lambung kapal. Mereka mengisap mineral dari kayu maupun besi sampai struktur cepat lapuk. Serangan pertama di dalam badai Rangkaruna memaksa rombongan Rama mempertahankan kapal sebelum ancaman lain muncul.','Tubuhnya panjang, lunak, dan bersegmen samar, dengan mulut pengisap bundar penuh gigi kecil. Kulit kelabu gelap mengembang setelah menyerap mineral. Beberapa sirip tipis membantu mengarahkan tubuh menuju lambung, sementara lendir membuatnya sulit dilepaskan. Saat menempel, hanya ekor yang tampak bergerak di antara ombak.','Parasit berkelompok yang mengikuti getaran serta mineral pada kapal. Ia tidak perlu menyerang awak secara langsung untuk menenggelamkan mereka. Setelah melekat, kawanan menyebar pada bagian bawah lambung dan mempertahankan gigitan. Benturan, cahaya, atau panas dapat mengganggu, tetapi efektivitas mekanis belum ditentukan.','Berbagai perairan Rangkaruna, terutama perbatasan badai dan jalur kapal. Sebutan semua perairan pada data lama menunjukkan persebaran luas, bukan kepadatan sama di setiap tempat.','Hisapan Pertama dalam Badai','Begitu kapal Rama menembus badai, lambung bergetar oleh hisapan basah. Lintah Palung telah menempel dari bawah. Hector dan Cassian harus mengusir kawanan sambil mempertahankan kapal dari ombak. Ancaman itu tampak kecil dibanding monster yang datang kemudian, tetapi satu lambung yang lapuk akan mengakhiri perjalanan sebelum mereka melihat palung.',[REG,WORLD,P5],['Kisah merangkum Prologue; Lifesteal legacy tidak dijadikan aturan naratif terhadap HP.']),
'Naga_Laut_Penghancur':('Naga Laut Penghancur','Naga air purba tanpa mata yang berburu melalui sonar listrik. Sisiknya menyimpan energi petir dari badai, lalu tubuhnya melesat keluar air untuk merobek tiang kapal. Ia merupakan pemangsa badai Rangkaruna dan tidak otomatis bagian dari Nagarasven Agnitra hanya karena disebut naga.','Tubuh panjang dan berotot dilapisi sisik biru kehitaman dengan garis listrik pada sisinya. Rongga mata tertutup sisik utuh; deretan organ sonar berada di sekitar rahang dan leher. Sirip besar menggantikan sayap, sedangkan cakar depan pendek membantu mencengkeram kayu. Tanduk pipih mengarahkan air ketika ia menembus permukaan.','Pemangsa aktif yang mengikuti pantulan suara dan medan listrik. Ia mengitari kapal dalam kedalaman, mengirim pulsa, lalu menyerang bagian tinggi setelah menyimpan petir. Suara keras dapat mengubah pembacaan arah, tetapi belum ditetapkan sebagai kelemahan. Ia menjadi agresif di zona badai tempat energinya mudah terisi.','Zona Badai Abadi Rangkaruna, antara permukaan yang disambar petir dan lapisan air tempat gema merambat jauh. Ia naik untuk menyerap energi lalu kembali berburu di bawah gelombang.','Tiang yang Menjawab Petir','Petir menyambar laut dan garis biru bergerak di bawah kapal kosong yang hanyut. Naga Laut mengirim pulsa ke arah tiang, menerima gema, lalu melesat menabraknya. Kayu patah jatuh ke air. Makhluk itu berputar sekali, menyadari tidak ada mangsa hidup, dan kembali ke badai mengikuti sambaran berikutnya.',[REG,WORLD],['Hubungan dengan Nagarasven tidak ditetapkan. Rupa sonar dan kisah ekologis merupakan usulan.']),
'Pari_Kematian_Besi':('Pari Kematian Besi','Pari purba selebar alun-alun dengan pelat alami sekeras baja dan ekor seperti tombak beracun. Dalam pelayaran Rama, seekor Pari melompat dari air dan mencoba menembus kubah pelindung Cassian.','Tubuhnya berupa cakram lebar berlapis pelat gelap yang saling menutup. Sirip dada bergerak seperti sayap berat. Mata berada pada sisi atas, sedangkan mulut tersembunyi di bawah. Ekor panjang berakhir pada duri logam alami dengan alur racun. Bekas goresan pada pelat menunjukkan benturan dengan karang dan kapal.','Buas ketika sesuatu melintas di atas wilayah dangkalnya. Ia mengumpulkan kecepatan di bawah air, melompat, lalu menggunakan ekor untuk menusuk dek atau pertahanan. Setelah serangan gagal ia kembali menyelam dan mencari sudut lain. Kekerasan pelat bukan bukti kebal terhadap seluruh serangan.','Perairan dangkal Rangkaruna dengan dasar cukup luas untuk memperoleh kecepatan dan karang sebagai perlindungan. Individu dapat memasuki jalur badai ketika mengikuti kapal.','Tombak dari Bawah Ombak','Selama tiga hari serangan Rangkaruna, Pari Kematian Besi melompat dari air dan mengayunkan ekor ke kubah Cassian. Tombak alaminya menghantam perlindungan tanpa mencapai geladak. Para pelaut tidak mengejarnya; mereka menjaga kubah dan terus bergerak, sebab satu serangan yang ditahan bukan jaminan makhluk itu telah pergi.',[REG,WORLD,P5],['Kisah merangkum Prologue; racun, hardness, dan penetrasi belum dikalibrasi.']),
'Paus_Penelan_Armada':('Paus Penelan Armada','Paus hitam sebesar gunung yang tidak sengaja memburu kapal, tetapi dapat menelan armada ketika membuka mulut untuk menyaring krill raksasa. Bahayanya lahir dari skala tubuh dan ketidakpedulian terhadap benda kecil di jalur makannya.','Tubuhnya hitam kelam dengan punggung luas menyerupai pulau bergerak. Mulut memenuhi bagian depan kepala dan memiliki lempeng penyaring besar. Bekas teritip serta karang kecil tumbuh pada kulit tua. Sirip samping bergerak lambat, tetapi satu kibasan menggeser air dalam volume besar. Lubang napas menghasilkan semburan yang terlihat melampaui kabut.','Cenderung tenang dan tidak sengaja menyerang. Ia mengikuti kawanan krill, membuka mulut, lalu terus berenang tanpa membedakan organisme dan kapal. Benturan atau suara dekat kepala dapat membuatnya berubah arah secara mendadak, menciptakan gelombang tambahan. Menyerangnya dapat memperburuk bahaya bagi armada di sekitar.','Tengah Laut Rangkaruna, pada jalur migrasi krill raksasa dan air cukup dalam untuk tubuhnya. Ia tidak lazim masuk ke pelabuhan atau karang dangkal.','Jalur Makan yang Berubah','Kawanan krill berpindah mengikuti arus malam. Paus besar berbelok bersama mereka, dan beberapa bangkai kapal hanyut tepat di depan mulutnya. Ia menelan semuanya tanpa memperlambat gerak. Setelah kawanan turun, paus menutup mulut dan menyelam; permukaan baru menunjukkan gelombang panjang setelah tubuhnya menghilang.',[REG,WORLD],['Perut tanpa dasar adalah hiperbola legacy; tidak dijadikan dimensi tak terbatas. Kisah ekologis usulan.']),
'Sirenia_Kegelapan':('Sirenia Kegelapan','Makhluk abyssal setengah perempuan dan setengah ikan yang bernyanyi dari balik kabut. Suaranya mengacaukan pikiran nakhoda serta kru sampai mereka saling menyerang atau mengarahkan kapal ke karang. Dalam Prologue, lolongannya mencoba mencuci otak Hector selama pelayaran Rangkaruna.','Bagian atas tubuh menyerupai perempuan pucat bermata menyala, berlanjut menjadi ekor ikan laut dalam dengan sirip robek. Rambut panjang menyatu dengan kabut dan air. Insang gelap membuka pada leher ketika ia bernyanyi. Gigi kecil tampak ketika melodi berubah menjadi lolongan. Wujud yang terlihat di kabut dapat dipengaruhi ilusi, sehingga tidak selalu sama dengan tubuh di air.','Memikat dari jarak jauh dan menghindari perlawanan langsung. Sirenia memindahkan sumber suara melalui gema, menguji ketakutan atau kecurigaan kru, lalu memperbesar konflik. Jika ditemukan, ia menyelam di antara karang. Kemampuan mental tidak membuktikan hubungan dengan Deepwater Siren Thalantira atau Asmodea.','Karang berkabut Rangkaruna, tempat gema dan pandangan terbatas membuat arah suara sulit dinilai. Jalur kapal di sekitar batu tajam menyediakan akibat mematikan bahkan tanpa serangan fisik.','Lolong di Hari Ketiga','Sirenia melolong dari kejauhan ketika kapal Rama telah tiga hari dihantam monster. Suara itu mencoba memasuki pikiran Hector, sementara kru yang kelelahan harus tetap menjaga arah. Mereka mempertahankan tugas dan menjauh dari karang tanpa mengejar penyanyi di kabut. Bertahan berarti menolak menjadikan setiap pikiran yang muncul sebagai perintah.',[REG,WORLD,P5],['Kisah merangkum Prologue. Hubungan dengan siren Thalantira dan mekanisme mental belum ditetapkan.']),
'Ubur_Ubur_Pijar_Kematian':('Ubur-Ubur Pijar Kematian','Kawanan ubur-ubur raksasa yang memancarkan cahaya biru dan sengatan pelumpuh. Pada malam hari pendar mereka dapat tampak seperti jalur aman, padahal seseorang yang jatuh di antara tentakel berisiko tenggelam tanpa mampu bergerak.','Kubah tubuhnya bening kebiruan dengan inti bercahaya yang berdenyut. Tentakel panjang menggantung dalam beberapa lapis; benang halus di antaranya sulit dilihat sebelum menyentuh kulit. Arus listrik melompat sebagai kilatan pendek ketika kawanan berdekatan. Ukuran individu berbeda-beda, menciptakan hamparan cahaya pada permukaan.','Mengikuti arus dalam kawanan dan tidak perlu mengejar korban. Kontak tentakel memicu sengatan, sedangkan gangguan keras dapat membuat beberapa individu melepaskan energi sekaligus. Dalam Prologue mereka menghantam lambung kapal hingga tampak meledak. Perilaku ini tidak memastikan bahwa ledakan selalu membunuh tubuh ubur-ubur atau merupakan tindakan sadar.','Permukaan Rangkaruna pada malam hari, terutama ketika arus membawa makanan dari kedalaman. Pendar mudah terlihat dalam air gelap, tetapi tentakel dapat menjangkau jauh di luar inti cahaya.','Laut yang Menyala','Kawanan Ubur-Ubur Pijar menghantam lambung kapal Rama di tengah tiga hari serangan. Cahaya biru menyala pada ombak, memaksa Hector dan Cassian melindungi kapal tanpa jatuh ke air. Di antara badai, keindahan pendar itu hanya memberi peringatan tentang tempat yang tidak boleh disentuh.',[REG,WORLD,P5],['Kisah merangkum Prologue. Kelumpuhan seketika dan ledakan belum diterjemahkan menjadi state/durasi game.'])}
def load(p): return json.loads(p.read_text(encoding='utf-8-sig'))
def write(p,o): p.write_text(json.dumps(o,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
def main():
 a=R/'pre_rangkaruna_narrative.json'
 if a.exists(): raise SystemExit('Batch archived already.')
 ps=sorted(F.glob('*.json')); assert {p.stem for p in ps}==set(E)
 write(a,{p.relative_to(ROOT).as_posix():p.read_text(encoding='utf-8-sig') for p in F.iterdir() if p.suffix in ('.md','.json')}); write(R/'pre_rangkaruna_hashes.json',{p.relative_to(ROOT).as_posix():hashlib.sha256(p.read_bytes()).hexdigest() for p in ROOT.rglob('*') if p.is_file() and '.git' not in p.parts and '_audit' not in p.parts and '__pycache__' not in p.parts})
 db={n:load(GAME/'data'/(n+'.json')) for n in ['Enemies','Skills','Items','Weapons','Armors']}
 for p in ps:
  o=load(p); title,d,f,b,h,st,s,sources,u=E[p.stem]; m=[x for x in db['Enemies'] if x and x['name']==title]; assert len(m)==1,p; enemy=m[0]
  t=f'---\ntitle: {title}\ntags:\n  - Bestiary\n  - Laut_Rangkaruna\n---\n\n# {title}\n'
  for x,y in [('Deskripsi',d),('Bentuk',f),('Tingkah Laku',b),('Habitat',h),('Kisah - '+st,s)]: t+=f'\n## {x}\n\n{y}\n'
  for x in sources: assert (ROOT/x).is_file(),x
  t+='\n> Catatan penulisan: Fakta dasar dan kejadian Prologue mengikuti sumber; rincian visual, ekologi, dan kisah lain merupakan usulan. Acuan: '+'; '.join('['+Path(x).stem.replace('_',' ')+'](../../'+quote(x,safe='/')+')' for x in sources)+'.\n'; p.with_suffix('.md').write_text(t,encoding='utf-8')
  old=dict(o); o['id']=p.stem; o['title']=title; o['category']='Bestiary'; o['description']=d.split('.')[0]+'.'; o['stat_status']=o['balance_status']='BLOCKED'; o['source_status']='legacy_with_runtime_observation'; o['legacy_values']=old
  o['presentation']={'markdown_role':'lore_only','lore_source':p.with_suffix('.md').relative_to(ROOT).as_posix(),'game_data_source':p.relative_to(ROOT).as_posix(),'narrative_status':'PROPOSED_ADDITIONS','approval':None,'scope':'Ten Rangkaruna fauna entries; earlier approvals do not extend.','sync_policy':'Author lore in Markdown; game data stays in JSON.'}; o['lore_review']={'source_archive':a.relative_to(ROOT).as_posix(),'sources':sources,'unresolved':u,'category_note':'Rangkaruna fauna; no automatic relation to similarly named Thalantira creatures.','historical_description':None}
  o['runtime_observation']={'status':'OBSERVED_ONLY','source':(GAME/'data/Enemies.json').relative_to(ROOT).as_posix(),'enemy':enemy,'skills':[db['Skills'][x['skillId']] for x in enemy['actions']],'drop_records':[{'database':{1:'Items',2:'Weapons',3:'Armors'}[x['kind']],'record':db[{1:'Items',2:'Weapons',3:'Armors'}[x['kind']]][x['dataId']]} for x in enemy['dropItems'] if x['kind']],'meaning':'Snapshot only; does not establish calibrated balance.'}; o['balance_review']={'stat_status':'BLOCKED','legacy_note':'Original object preserved in legacy_values; not recalibrated.','authority':'06_Sistem Game & Ekonomi/Pedoman_Pemberian_Stat.md','simulation_result':None,'playtest_evidence':None}; write(p,o)
 print('Rangkaruna narrative batch: 10 pairs.')
if __name__=='__main__': main()
